"""Append source-specific reasoning to 07-001..028 without changing old content."""
import hashlib,json,re
from pathlib import Path
root=Path(__file__).resolve().parents[2]
folder=root/'tasks/001-russian-history-course'
assert not (folder/'imperial-deep-original.json').exists(),'Already applied: do not append twice'
assert not (folder/'imperial-deep-validation.json').exists(),'Validation artifact already exists'
addition={
'07-001':'''Проверить это различие удобно на указе о вольных хлебопашцах: возможность освобождения и число людей, действительно ею воспользовавшихся, являются разными результатами. Для объяснения ограниченного применения недостаточно объявить реформу неискренней. Нужно выяснить, кто принимал решение, как согласовывались земля и условия освобождения и какие препятствия встречались сторонам. Обзор царствования задаёт последовательность преобразований, но не заменяет документа об отдельной сделке. Сравните также две области политики — устройство министерств и крестьянские отношения. Государь мог одновременно поддерживать изменение управления и сохранять зависимость основной массы сельского населения. Разная глубина перемен объясняется устройством соответствующих отношений и интересами участников, а не обязательно одним неизменным намерением правителя.''',
'07-002':'''Возьмите проект 1809 года и проследите мысленный спор: исполнительное учреждение считает действие необходимым, а орган, обсуждающий закон, ему возражает. Кто назначает участников, вправе ли сторона отказаться и чьё решение обязательно? Это вопросы к тексту, а не утверждение, что подобный спор действительно состоялся. Затем сопоставьте проектируемую систему с реально созданным Государственным советом. Нельзя переносить полномочия задуманной общегосударственной думы на учреждение с другим порядком формирования. Отдельный вопрос — кого представляет многоступенчатое представительство: имущество и сословное положение меняли доступ к участию. Такой разбор позволяет увидеть одновременно новизну юридического замысла и пределы участия, не превращая Сперанского ни в современного демократа, ни в автора пустой канцелярской схемы.''',
'07-003':'''Тильзитский договор полезно читать как набор обязательств, принятых сторонами в конкретной обстановке. Затем для каждого хозяйственного последствия постройте цепочку: запрет, изменение поведения торговца, затрата на обход и результат для производителя или покупателя. Доход помещика, цена импортного товара и государственный таможенный сбор могут меняться неодинаково. Это объясняет, почему оценка блокады зависит от выбранной группы. Нейтральный флаг также не устанавливает происхождение груза без сопроводительных сведений. Если исследователь располагает только общим годовым оборотом, он может обнаружить изменение, но не уверенно распределить его между блокадой, войной и урожаем. Называя предполагаемый механизм, укажите, какое свидетельство отличило бы его от конкурирующего объяснения.''',
'07-004':'''Для объяснения отступления важны не только расстояния, но и движение запасов. Условно поставьте рядом походный приказ, ведомость численности и сообщение о продовольствии: каждый документ показывает отдельную сторону возможности продолжать кампанию. Приказ свидетельствует о намерении командования, но не доказывает своевременного исполнения. Сокращение числа людей в строю не равняется числу погибших в бою: требуется различать убитых, раненых, больных, пленных, отставших и выделенные отряды. Категории и даты ведомостей должны совпадать. Тогда вопрос о роли погоды можно поставить точнее: какие трудности существовали раньше, какие усилились позднее и почему армия не смогла компенсировать их снабжением. Такой анализ связывает географию с решениями и ресурсами, не заменяя всю войну одной причиной.''',
'07-005':'''Даже числовое сравнение потерь требует одинакового времени подсчёта. Раннее донесение может не включать пропавших или умерших позднее от ран, а итоговая ведомость — охватывать более продолжительный период. Сначала установите, что считалось человеком в строю и кого относили к потерям, затем сравнивайте доли. Описание позиции после боя тоже нуждается в точной дате: занятие участка днём и владение им после завершения сражения не одно и то же. Материал о поле Бородина помогает поставить пространственный вопрос, но отдельное сохранившееся укрепление не объясняет решений всех командиров. Связь с исходом кампании устанавливают через последующие приказы и состояние армий; иначе позднейшая победа подменяет непосредственный результат сражения.''',
'07-006':'''Вклад союзника может состоять не только в числе солдат на поле. Он способен обеспечить направление снабжения, вынудить противника удерживать войска в другом месте или согласиться на политический компромисс, сохранивший коалицию. Чтобы сравнить такие вклады, сначала укажите конкретный результат: выигранное сражение, продолжение кампании или согласованный мир. Исторический обзор и художественная сатира о Наполеоне отвечают на разные вопросы: второй источник особенно важен для изучения восприятия врага, а не для проверки численности войск. Утверждение «без этого участника победа невозможна» требует обоснованной альтернативы. Нельзя просто вычесть его людей из уже состоявшейся коалиции и предположить, что решения всех остальных остались бы неизменными.''',
'07-007':'''Заключительный акт конгресса устанавливает согласованные границы и обязательства, но сам факт подписи не раскрывает весь ход переговоров. Для восстановления компромисса нужно отдельно искать первоначальные предложения, возражения и изменения позиции. Сопоставьте формулировку о принадлежности территории с устройством прав её населения: династическая передача, административная автономия и личные права представляют разные уровни решения. Отсутствие подписи сообщества под международным актом не показывает автоматически его единодушное неприятие, как и торжественное обращение элиты не доказывает поддержки всех жителей. Если необходимы сведения о местных настроениях, составьте перечень групп, чьи свидетельства сохранились, и тех, чей голос отсутствует. Это помогает увидеть пределы утверждения о «согласии Европы».''',
'07-008':'''Сопоставляя проекты Муравьёва и Пестеля, задайте одинаковые вопросы об устройстве власти, земле и допуске к политическому участию. Затем проверьте, какие положения были личным предложением автора, какие обсуждались обществом и какие действительно стали согласованной целью. Черновик не равен принятой программе всей организации. Аналогично нужно различать осведомлённость о тайном обществе, членство и участие в вооружённом выступлении. Следственная комиссия могла объединять эти обстоятельства для задачи обвинения; историк обязан восстановить степень подтверждения каждого. Поздние воспоминания добавляют опыт наказания и последующую самооценку, которых не было в момент решения. Различие между ранним письмом и поздним рассказом может объясняться изменением взгляда, а не только намеренной ложью.''',
'07-009':'''Для проверки действия законов выберите одну процедуру, например возможность подданного оспорить решение чиновника, и проследите весь путь обращения. Важно не только существование нормы, но и понятность порядка, стоимость обращения, срок рассмотрения и возможность исполнения результата. Нельзя заранее считать каждую жалобу успешной или заведомо бесполезной. Свод законов позволяет выяснить формальные правила на определённый момент, а сведения о конкретных делах — границы их применения. Сословные различия требуют отдельных сравнений: одинаковое название обращения могло сопровождаться разными возможностями заявителя. Биографический материал о Николае I помогает понять образ правления и представление о службе, но не способен сам измерить независимость учреждений или защиту населения от произвола.''',
'07-010':'''Для автора философской статьи публичная дискуссия могла быть способом влияния без создания формальной организации. Поэтому отсутствие общего членского списка не означает отсутствия общественного значения. Проследите другой механизм: кто издавал текст, кто его читал, как его пересказывали и какие ответы он вызывал. При этом тираж показывает возможность распространения, а не число согласившихся читателей. Материал об интеллектуальной культуре помогает связать идеи с местом их обсуждения, но нельзя считать всех посетителей салона сторонниками одного направления. Полицейское дело полезно для изучения надзора и связей между людьми; его обвинительная категория нуждается в самостоятельной проверке. Общественное движение возникает через повторяющиеся связи и действия, а не только через позднее удобное название.''',
'07-011':'''Названия «славянофилы» и «западники» помогают сравнить ответы на общие вопросы, но не отменяют различий внутри направлений. Выберите один предмет, например крепостную зависимость или отношение к петровским преобразованиям, и сопоставьте датированные тексты отдельных авторов. Их позиции могли изменяться, поэтому цитаты разных лет нельзя без пояснения соединять в одну программу. Образ Европы у мыслителя также не равен описанию всех европейских стран: иногда это нравственный пример или полемическое обобщение. Аналогично «древняя община» могла обозначать желательный порядок, а не восстановленную повседневную практику. Полезный результат сравнения — показать, каким доводом автор связывает прошлое с предлагаемым будущим и какое историческое свидетельство способно проверить этот довод.''',
'07-012':'''Различие рамок касается и пространства. Взгляд из Севастополя, с Балтики или с Кавказа показывает разные задачи войск и снабжения, поэтому рассказ об одной осаде нельзя автоматически распространить на всю войну. Музейный обзор удобен для последовательности и материальной стороны кампании, но объяснение поражения требует сопоставления ресурсов и решений сторон. Техническое преимущество противника не означает, что любой отдельный исход был заранее предопределён. Уточните, какая технология применялась, в каких условиях и что мешало компенсировать её действие. Затем отделите военный результат от дипломатического: условия мира зависели также от союзов и готовности продолжать борьбу. Это позволяет объяснить пределы имперских возможностей, не превращая один вид вооружения в универсальную причину.''',
'07-013':'''Сопоставьте для одной реформы три момента: обсуждение проекта, утверждение правил и начало работы учреждения в выбранной местности. Между ними могли пройти время и дополнительные решения. Энциклопедический обзор Великих реформ помогает увидеть их связь, но местное осуществление требует сведений о деньгах, сотрудниках и сопротивлении заинтересованных групп. Отдельно выясните, кто получал новое право и кто терял прежнее полномочие. Изменение могло расширить самостоятельность одного сословия, сохранив ограничения для другого. Реформатор действует через учреждения, советников и исполнителей, поэтому полезно распределить авторство между подготовкой, утверждением и практическим проведением. Это уточняет личную роль Александра II без подмены анализа либо благодарственной биографией, либо объяснением всех ограничений одним характером монарха.''',
'07-014':'''Аграрное исследование направляет внимание на права собственности и условия пользования, а общий обзор реформ — на политическую последовательность. Для конкретной деревни потребовались бы уставная грамота, данные о наделе и повинностях, затем сведения о переходе к выкупу. Эти документы нельзя заменить средним размером надела по империи. Сравнение должно учитывать качество почвы, расположение угодий и доступ к промыслу: равная площадь могла обеспечивать разный доход. Освобождённая семья также не равна неизменной единице наблюдения, поскольку число работников и иждивенцев менялось. Если после реформы возник долг, выясните его основание и получателя платежа. Такой путь связывает юридическое освобождение с повседневной самостоятельностью и показывает, какие именно ограничения сохранялись.''',
'07-015':'''Рассмотрите связь двух преобразований: новый порядок суда давал иной способ разрешать спор, а местное самоуправление создавало учреждения, решения которых также затрагивали интересы жителей. Но из одновременного появления реформ не следует, что их практические возможности были одинаковыми повсюду. Для проверки выберите территорию и год, установите, какие органы уже работали, кому они были доступны и какие дела оставались вне их полномочий. Обзорная статья даёт общие принципы, тогда как первичный устав определяет процедуру и исключения. Затем сопоставьте установленное правило со сведениями о его использовании. Жалоба на недостатки нового учреждения сама по себе не доказывает бесполезности реформы: возможность предъявить требование могла быть одним из её результатов.''',
'07-016':'''Чтобы понять неудачу пропаганды, недостаточно представить крестьянина неграмотным или революционера оторванным от жизни. Сначала восстановите содержание предложения и обстоятельства встречи. Разговор о будущем справедливом устройстве мог не отвечать на ближайший земельный спор или риск наказания конкретной семьи. Отказ слушателя не доказывает согласия с существующей властью: мотивом могла быть осторожность либо недоверие к незнакомцу. Энциклопедическая статья о народничестве помогает различать течения, но позднейший переход части участников к политическому насилию нельзя переносить на всех пропагандистов заранее. Для конкретного эпизода сопоставьте листовку, рассказ участника и документ о реакции деревни, учитывая, кто записал слова и чьи интересы представлял.''',
'07-017':'''Промышленный переворот означает изменение способов производства и организации труда, поэтому рост денежной выручки без сведений о технологии ещё не устанавливает его глубину. Цена продукции могла измениться независимо от её количества. Отраслевые данные полезно сопоставлять с числом занятых и продолжительностью рабочего времени: больший выпуск не обязательно означает большую производительность каждого часа. Источник об основных этапах формирования рабочих кадров позволяет спросить также, откуда приходили работники и сохраняли ли связи с деревней. Однако административная запись о занятии не раскрывает весь годовой труд человека. Для объяснения перехода от промысла к фабрике нужны сопоставимые наблюдения во времени, а не простое противопоставление «ручного прошлого» и «машинного будущего».''',
'07-018':'''Законодательные акты показывают решения власти, но не дают готового ответа об их одинаковом исполнении по всей стране. Сравните для выбранной меры заявленную цель, расширенное полномочие администрации и реальную возможность подданного защитить свои интересы. Если исследуется безопасность, отдельно определите, идёт ли речь о границах государства, повседневном насилии или устойчивости дохода семьи. Эти показатели могут изменяться в разные стороны. Официальный юбилейный текст или памятное прозвище особенно полезны как свидетельство создаваемого образа императора; их нельзя использовать вместо данных о населении. При обсуждении союза с Францией различайте внутренний строй партнёра и конкретную выгоду дипломатического сотрудничества. Это позволяет объяснить выбор без предположения, что государства всегда объединяются только по идейному сходству.''',
'07-019':'''Положение о земских участковых начальниках 1889 года позволяет разобрать устройство власти по статьям: откуда берётся полномочие, на кого распространяется и куда может обратиться несогласный. Затем сравните этот порядок с выборным земским собранием. Одинаковое слово «земский» указывает на местный круг дел, но не устанавливает одинакового представительства. Для оценки контрреформы важно выяснить, какое прежде существовавшее право изменилось и для какой группы. Общая характеристика «возвращение назад» скрывает различия между восстановлением старой нормы, созданием нового инструмента надзора и ограничением практической самостоятельности. Закон устанавливает допустимое действие начальника; жалобы и разбирательства потребовались бы, чтобы показать, как он пользовался полномочиями. Само расширение надзора не доказывает ни улучшения порядка, ни исчезновения произвола.''',
'07-020':'''Выставка о Витте помогает поставить вопрос о связи валютной устойчивости, государственных заказов и железнодорожного строительства. Однако перечисление мер министра не показывает величину вклада каждой из них в промышленный рост. Чтобы проверить механизм, потребуются условия кредита, спрос на оборудование и положение предприятий до получения заказа. Общая динамика кадров промышленности раскрывает ещё одну сторону: расширение выпуска могло идти вместе с притоком новых работников и перераспределением труда. Если обсуждается зависимость от иностранного капитала, уточните форму вложения, получателя дохода и обязательства перед инвестором. Сам иностранный источник денег не определяет заранее ни пользу, ни ущерб. Важно показать, какие возможности появились и какие платежи или ограничения возникли вслед за ними.''',
'07-021':'''Сравнение направлений полезно начинать с общего вопроса, например кто должен изменить общественный порядок и каким способом. Затем отдельно укажите желаемый строй, предполагаемую социальную опору и допустимые средства борьбы. Согласие по отмене одного ограничения не означает единства по собственности, представительству или насилию. Энциклопедическая статья о народниках описывает течение, но не может сама установить численность всех его организаций в выбранном городе. Для этого нужны списки, переписка и сведения о совместных действиях с поправкой на неполноту сохранения. Важно также различать способность распространять идеи и способность координировать поступки. Политическая известность автора может превосходить организационные ресурсы его сторонников, а малочисленная группа — иметь непропорционально большое влияние на публичную дискуссию.''',
'07-022':'''Музейный материал о передвижниках раскрывает устройство художественной деятельности, но выставленный в музее шедевр не показывает автоматически опыт всей публики XIX века. Спросите, где и при каких условиях зритель мог видеть произведение, как о нём писали и кто покупал картины. Художественная критика одновременно свидетельствует о восприятии и пытается направить его, поэтому похвала не равна общему мнению общества. С научным открытием следует поступать сходно: отделять первоначальное сообщение, проверку другими специалистами и позднейшее распространение в образовании. Источники этого урока подробнее освещают искусство и общественную мысль, чем отдельные естественно-научные открытия. Поэтому точное утверждение о приоритете учёного потребовало бы дополнительной датированной публикации, а не переноса музейного авторитета на другую область.''',
'07-023':'''Для сравнения городской рабочей и сельской крестьянской семьи сначала определите период наблюдения и состав хозяйства. Денежная зарплата могла покрывать покупку того, что другая семья производила сама, но самостоятельное производство требовало земли, инвентаря и рабочего времени. Нельзя считать его бесплатным. Средний годовой доход также скрывает сезонность поступлений и расходы в момент болезни или неурожая. Общая глава о крестьянах и сельском хозяйстве задаёт эти вопросы, но не заменяет конкретной расходной записи. В мемуаре особенно заметное событие могло вытеснить обычный ежедневный труд, а полицейская или фабричная ведомость учитывала категории, нужные учреждению. Укажите, чьи занятия источник оставляет невидимыми, прежде чем делать вывод о «типичном» уровне жизни.''',
'07-024':'''Исследование управления империей помогает отказаться от предположения, что одна норма действовала одинаково во всех областях и для всех групп. Сначала выберите территорию, учреждение и период, затем восстановите, какие правила применялись к языку, вероисповеданию, собственности и службе. Сопоставление закона с местным распоряжением позволяет увидеть разницу между общей политикой и способом её осуществления. При этом административная категория народа не обязательно совпадает с самоназванием жителей и их политическими целями. Обращение местного представителя также нельзя автоматически считать голосом всего населения. Разделите позиции земледельцев, кочевых хозяйств, торговцев и образованных посредников, если источники позволяют это сделать. Тогда интеграция предстаёт как изменение конкретных прав и отношений, а не как однозначно благополучный или неизменно одинаковый для всех процесс.''',
'07-025':'''Обзор внешней политики позволяет увидеть последовательность решений, а текст договора — конкретные обязательства сторон. Но объяснение дипломатического выбора требует ещё вопроса о доступных альтернативах и цене продолжения конфликта. Уступка могла быть способом сохранить другие позиции; без анализа переговоров нельзя автоматически считать её признаком слабости или личного предпочтения монарха. Затем проследите, что означало изменение границы на местности: кто собирал налоги, какой суд рассматривал споры и могла ли семья продолжать пользоваться прежними угодьями. Ответы не выводятся из одной линии на карте. Если население перемещалось, различайте добровольный поиск возможностей, бегство от угрозы и принудительное выселение. Для каждого механизма нужны собственные свидетельства, даже когда дипломатический итог уже надёжно установлен.''',
'07-026':'''Университетская историческая справка показывает инициативу открытия курсов, а архивная карточка фонда указывает, какие группы документов могут сохраниться для подробного исследования. Наличие дела в описи ещё не означает, что содержащиеся в нём сведения уже прочитаны и подтверждают выбранный вывод. Для изучения барьера полезно поставить рядом условия приёма, размер необходимых расходов и возможности последующего заработка. Слушательницы, дошедшие до выпуска, представляют отобранную группу: их успех не показывает судьбу всех желавших учиться. Письма и прошения помогают восстановить мотивы, но решение семьи могло сочетать стремление к знаниям с хозяйственной необходимостью. Такое сопоставление позволяет объяснить расширение женской самостоятельности через реальные возможности и ограничения, не объявляя открытие аудитории завершением борьбы за равноправие.''',
'07-027':'''Для объяснения успеха земства полезно проследить одно решение от сметы до услуги. Выделение денег на школу ещё не означает, что здание открыто, учитель найден, а дети могут посещать занятия круглый год. Протокол собрания показывает обсуждение приоритетов, отчёт управы — исполнение, а сведения о посещаемости — другую сторону результата. Все три документа создаются заинтересованными учреждениями и нуждаются в сопоставлении. Сравнивая уезды, учитывайте не только богатство, но и расселение: одинаковое число школ при разной протяжённости территории даёт разную доступность. Для доказательства влияния земства нужны также изменения во времени. Хороший результат после открытия учреждения не исключает участия других причин, например роста доходов семей или деятельности иных образовательных организаций.''',
'07-028':'''Судебный отчёт нужно читать по ролям: обвинитель доказывает свою версию, защитник оспаривает её, свидетель сообщает воспринятые обстоятельства, а решение устанавливает процессуальный итог. Яркая речь адвоката не является независимым подтверждением каждого изложенного факта. Отдельно проверьте, какие вопросы были поставлены присяжным и какие дела вообще могли попадать в этот порядок. Иначе известный оправдательный вердикт легко принять за доказательство полной независимости всего правосудия. Публичность позволяет наблюдать разбирательство, но газетный пересказ может выбирать наиболее эффектные реплики. Для оценки реформы сравнивайте не только исходы, но и доступ к защите, порядок исследования свидетельств и способы обжалования. Новая процедура важна тем, как ограничивает возможность осудить без достаточного доказательства, даже когда общественная оценка поступка остаётся отрицательной.''',
}
assert set(addition)=={f'07-{i:03}' for i in range(1,29)}
prepared=[];snapshot=[];checks=[]
for lid,extra in addition.items():
 p=root/f'src/content/lessons/{lid}.json';x=json.loads(p.read_text())
 assert x['id']==lid and x['status']=='written',(lid,'unexpected status')
 original=x['deep']['text'];before=json.loads(json.dumps(x))
 signature=json.loads(json.dumps(x));signature['deep'].pop('text')
 digest=hashlib.sha256(json.dumps(signature,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
 snapshot.append({'id':lid,'deep':dict(x['deep']),'status':x['status'],'sources':list(x['sources']),'otherFieldsSha256':digest})
 x['deep']['text']=original+'\n\n'+extra
 afterWords=len(re.findall(r'\S+',x['deep']['text']))
 assert afterWords>=100,(lid,afterWords)
 restored=json.loads(json.dumps(x));restored['deep']['text']=original
 assert restored==before,(lid,'other fields changed')
 prepared.append((p,x))
 checks.append({'id':lid,'wordsBefore':len(re.findall(r'\S+',original)),'wordsAdded':len(re.findall(r'\S+',extra)),'wordsAfter':afterWords,'prefixPreserved':x['deep']['text'].startswith(original+'\n\n'),'status':x['status'],'otherFieldsUnchanged':restored==before})
# Save the originals before updating lesson files.
for name,data in [('imperial-deep-original.json',snapshot),('imperial-deep-validation.json',checks)]:
 with (folder/name).open('x') as f:json.dump(data,f,ensure_ascii=False,indent=2);f.write('\n')
for p,x in prepared:
 with p.open('w') as f:json.dump(x,f,ensure_ascii=False,indent=2);f.write('\n')
print('Expanded',len(checks),'imperial deep texts;',min(x['wordsAfter'] for x in checks),'–',max(x['wordsAfter'] for x in checks),'words; all original prefixes and other fields preserved')
